from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = set()
            markers = set()
            while q:
                x, y = q.popleft()
                comp.add((x, y))
                if grid[x][y] not in (0, 1):
                    markers.add(grid[x][y])
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] != 0 and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        q.append((nx, ny))
            if not markers:
                continue
            color = min(markers)
            for x, y in comp:
                if grid[x][y] != 1 or not (0 < x < h - 1 and 0 < y < w - 1):
                    continue
                if all(grid[i][j] == 1 for i in range(x - 1, x + 2) for j in range(y - 1, y + 2) if (i, j) != (x, y)):
                    out[x][y] = color
    return out
